#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <time.h>

int main(void){
  const size_t N = 1<<26; // ~67M
  uint64_t *A = (uint64_t*)aligned_alloc(64, N*sizeof(uint64_t));
  uint64_t *B = (uint64_t*)aligned_alloc(64, N*sizeof(uint64_t));
  for(size_t i=0;i<N;i++){ A[i]=i; B[i]=0; }

  struct timespec t1,t2; 
  clock_gettime(CLOCK_MONOTONIC_RAW, &t1);
  for(size_t i=0;i<N;i++) B[i] = A[i];
  clock_gettime(CLOCK_MONOTONIC_RAW, &t2);
  double t = (t2.tv_sec - t1.tv_sec) + (t2.tv_nsec - t1.tv_nsec)/1e9; 
  printf("stride1: %f s\n", t);
  // add pattern 2 and 3 similarly
}
```

