// Pseudo-code: TLB lookup and refill
function tlbLookup(vpn){
  const idx = vpn % 128;
  const e = tlb[idx];
  if (e && e.vpn === vpn && e.valid) return e.pte;
  return null;
}
function tlbRefill(vpn, pte){
  const idx = vpn % 128;
  tlb[idx] = { vpn, pte, valid: true, ts: Date.now() };
}
```

